<template><div v-if="operation" class="modal-backdrop" @keydown.esc="close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="operation-title"><header class="panel-header"><h2 id="operation-title">确认运维操作</h2><button :disabled="busy" @click="close" aria-label="关闭">关闭</button></header><form class="panel-body" @submit.prevent="submit"><dl class="facts"><dt>操作</dt><dd>{{labels[operation.spec.action]||operation.spec.action}}</dd><dt>目标资源</dt><dd><code>{{operation.plan.target}}</code></dd><dt>作用节点</dt><dd>{{operation.node}}</dd><dt>数据保留</dt><dd>保留持久化卷；不执行强制删除</dd></dl><div v-if="operation.plan.externalManagement" class="notice warning">此资源由其他编排系统创建，请使用所属应用的运维流程。</div><label>输入目标名称确认<input ref="confirmationInput" v-model="confirmation" :placeholder="operation.plan.target" autocomplete="off" required></label><p v-if="error" class="notice danger" role="alert">{{error}}</p><footer class="form-actions"><button type="button" :disabled="busy" @click="close">取消</button><button class="primary" :disabled="busy || confirmation!==operation.plan.target || operation.plan.readOnly">{{busy?'提交中…':'确认并执行'}}</button></footer><p v-if="operation.plan.readOnly" class="muted">当前执行器为只读模式，不能执行变更。</p></form></section></div></template>
<script setup>
import {ref,watch,nextTick} from 'vue';import {useRouter} from 'vue-router';import {useOperations} from '../../composables/useOperations';
const {operation,error,busy,execute,close}=useOperations(),router=useRouter(),confirmation=ref(''),confirmationInput=ref(null);
const labels={'container.create':'创建容器','container.start':'启动容器','container.stop':'停止容器','container.restart':'重启容器','container.delete':'删除容器','image.delete':'删除镜像','image.tag':'创建版本标签','volume.create':'创建数据卷'};
watch(operation,async()=>{confirmation.value='';await nextTick();confirmationInput.value?.focus();});
async function submit(){try{const {node,job}=await execute(confirmation.value);router.push(`/tasks/operation/${node}/${job.id}`);}catch{/* retained in dialog */}}
</script>
